  const COMMIT_HE = /(?:מתחייב|מתחייבת|אאשר עד|אחזיר לך|אני על זה|(?:^|[^\u0590-\u05FF])(?:אשלח|נשלח|אעביר|נעביר|אכין|נכין|אגיש|נגיש|אשלם|נשלם|אחזיר|נחזיר)(?![\u0590-\u05FF]))/;
